/** Sample documents for the prototype, embedded as base64 because files of these types cannot be attached to a published page. */
export const SAMPLES: Record<string, string> = {
    'letter.docx':
        '',
    'budget.xlsx':
        '',
    'deck.pptx':
        '',
    'letter.doc':
        '',
    'budget.xls':
        '',
    'deck.ppt':
        '',
    'notes.txt':
        'U2hvcHBpbmcgbGlzdAotIG1pbGsKLSBicmVhZAotIHRlYQoKUmVtZW1iZXIgdG8gY2FsbCB0aGUgbGFuZGxvcmQuCg==',
    'people.csv':
        'bmFtZSxjaXR5LGFnZQpNaXJhLFZpZW5uYSwzMQpUb2JpYXMsR3JheiwyOAoiTGVuYSwgQi4iLFZpbGxhY2gsMzUK',
    'report.pdf':
        '',
};

export function sampleResponse(name: string): Response | null {
    const data = SAMPLES[name];
    if (!data) return null;
    const bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
    return new Response(bytes);
}
